mapper.select:
SELECT /* getUserMenuList */
FROM ( SELECT R.MENU_NUMB , R.SUBX_NUMB , R.MENU_NAME , R.MENU_URLX , R.SORT_ORDR , R.SHOW_YSNO , R.SHOW_YSNO_NAME , R.USEE_YSNO , R.USEE_YSNO_NAME , R.REGI_ADMN , R.REGI_ADMN_NAME , R.REGI_DATE , R.UPDT_ADMN , R.UPDT_ADMN_NAME , R.UPDT_DATE , ROW_NUMBER() OVER ( ORDER BY COALESCE(R.SORT_ORDR, 9999) , CAST(R.MENU_NUMB AS UNSIGNED) ) AS ROW_NUMB FROM ( SELECT FROM TM_URMENU M WHERE M.SUBX_NUMB = #{topMenuSubxNumb}
ORDER BY COALESCE(M.SORT_ORDR, 9999) , CAST(M.MENU_NUMB AS UNSIGNED) ) R ) P WHERE P.ROW_NUMB BETWEEN #{startRow} AND #{endRow} ORDER BY P.ROW_NUMB


SELECT /* getUserMenuDtl */

  FROM TM_URMENU
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}



  SELECT /* getUserSubMenuList */

    FROM TM_URMENU
   WHERE MENU_NUMB = #{menuNumb}
     AND SUBX_NUMB != #{topMenuSubxNumb}
ORDER BY COALESCE(SORT_ORDR, 9999)
       , CAST(SUBX_NUMB AS UNSIGNED)

mapper.insert:
/* setUserMenu */
INSERT INTO TM_URMENU (
            MENU_NUMB
          , SUBX_NUMB
          , MENU_NAME
          , MENU_URLX
          , SORT_ORDR
          , SHOW_YSNO
          , USEE_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{menuNumb}
          , #{subxNumb}
          , #{menuName}
          , #{menuUrlx}
          , #{sortOrdr,jdbcType=NUMERIC}
          , #{showYsno}
          , #{useeYsno}
          , #{regiAdmn}
          , CURRENT_TIMESTAMP
          , #{updtAdmn}
          , CURRENT_TIMESTAMP
)

mapper.update:
UPDATE /* uptUserMenu */
       TM_URMENU
   SET MENU_NAME = #{menuName}
     , MENU_URLX = #{menuUrlx}
     , SORT_ORDR = #{sortOrdr,jdbcType=NUMERIC}
     , SHOW_YSNO = #{showYsno}
     , USEE_YSNO = #{useeYsno}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}

mapper.delete:
DELETE /* delUserMenu */
  FROM TM_URMENU
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}
